using System.Globalization;

string sku = "0012";
int quantity = 3;
decimal unitPrice = 2.50m;
bool active = true;

quantity = quantity + 1;
decimal total = unitPrice * quantity;
Console.WriteLine($"{sku}: {quantity} units, active={active}");
Console.WriteLine(total.ToString("F2", CultureInfo.InvariantCulture));
Console.WriteLine(9 / 4);
Console.WriteLine((9m / 4).ToString(CultureInfo.InvariantCulture));

Console.WriteLine("Enter a quantity:");
string? input = Console.ReadLine();
if (!int.TryParse(input, out int quantity))
{
    Console.WriteLine("Enter a whole number.");
    return;
}

if (quantity <= 0)
{
    Console.WriteLine("Quantity must be positive.");
    return;
}

Console.WriteLine($"Recorded: {quantity}");

int stock = 5;
int wanted = 5;

if (wanted <= 0)
{
    Console.WriteLine("Invalid quantity");
}
else if (wanted > stock)
{
    Console.WriteLine("Insufficient stock");
}
else
{
    stock = stock - wanted;
    Console.WriteLine("Issue recorded");
}
Console.WriteLine($"Remaining: {stock}");
